(x, y, t) => {
  const wx = Math.sin(x * 0.02 + t * 0.3) * 12 + Math.cos(y * 0.015 - t * 0.2) * 8;
  const wy = Math.cos(y * 0.02 - t * 0.25) * 12 + Math.sin(x * 0.018 + t * 0.35) * 8;
  const sx = x + wx, sy = y + wy;

  // Prime-based sources
  const primes = [2, 3, 5, 7, 11, 13, 17, 19];
  const src = [];
  for (let i = 0; i < 8; i++) {
    const p = primes[i];
    src.push([
      60 + i * 55 + Math.sin(t * 0.3 / p) * 40,
      30 + (p % 5) * 45 + Math.cos(t * 0.4 / p) * 30,
      0.02 * p + 0.03,
      0.8 + p * 0.15
    ]);
  }

  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx - sX) ** 2 + (sy - sY) ** 2);
    aS += Math.sin(d * f - t * sp);
    iS += Math.sin(d * f * 0.7 + t * sp * 0.6 + 1.5);
  }
  const act = aS / 8, inh = iS / 8;

  // Prime-modulated background field
  let bg = 0;
  for (let i = 0; i < 4; i++) {
    const p = primes[i];
    bg += Math.sin(sx * 0.01 * p + sy * 0.008 * p + t * 0.5 / p);
  }
  bg /= 4;

  const cx = 240, cy = 120;
  const dist = Math.sqrt((sx - cx) ** 2 + (sy - cy) ** 2);
  const ang = Math.atan2(sy - cy, sx - cx);
  const spiral = Math.sin(dist * 0.05 - ang * 5 - t * 1.5) * Math.cos(dist * 0.03 + ang * 3 + t);

  const reaction = Math.tanh((act - inh * 0.6 + bg * 0.3 + spiral * 0.4) * 2.5);

  // Neon palette
  const pal = [
    [2, 4, 15],      // deep dark
    [0, 20, 60],     // dark blue
    [0, 180, 255],   // cyan
    [0, 255, 180],   // electric green
    [255, 255, 100], // yellow
    [255, 50, 200],  // hot pink
    [180, 0, 255],   // purple
    [255, 255, 255]  // white
  ];

  const v = reaction * 0.5 + 0.5;
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;

  let r = pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f;
  let g = pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f;
  let b = pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f;

  // UI elements
  // Window frames
  const win1x = 20, win1y = 15, win1w = 200, win1h = 90;
  const win2x = 260, win2y = 135, win2w = 200, win2h = 85;

  // Check if inside window 1
  const inW1 = x >= win1x && x < win1x + win1w && y >= win1y && y < win1y + win1h;
  const inW2 = x >= win2x && x < win2x + win2w && y >= win2y && y < win2y + win2h;

  // Window borders
  const bdr1 = inW1 && (x - win1x < 2 || win1x + win1w - x < 2 || y - win1y < 2 || win1y + win1h - y < 2);
  const bdr2 = inW2 && (x - win2x < 2 || win2x + win2w - x < 2 || y - win2y < 2 || win2y + win2h - y < 2);

  // Title bars
  const title1 = inW1 && y - win1y < 14;
  const title2 = inW2 && y - win2y < 14;

  // Status bar at bottom
  const statusBar = y >= 225 && y < 239;

  // Grid lines with prime spacing
  let gridLine = 0;
  for (const p of primes.slice(0, 5)) {
    if ((x % (p * 20)) < 1 || (y % (p * 20)) < 1) gridLine = 0.15;
  }

  // Data bars inside windows
  let dataBar = 0;
  if (inW1 && y > win1y + 20) {
    const barIdx = ((y - win1y - 20) / 8) | 0;
    const barVal = Math.sin(t * 0.5 + barIdx * 0.7) * 0.5 + 0.5;
    const barW = barVal * (win1w - 20);
    if (x - win1x - 10 < barW && x - win1x - 10 > 0) {
      dataBar = 0.3 * barVal;
    }
  }

  // Prime number visualization in window 2
  let primeViz = 0;
  if (inW2 && y > win2y + 20) {
    const px = x - win2x - 10;
    const py = y - win2y - 20;
    const num = (py * 14 + (px / 3)) | 0;
    // Simple primality test approximation
    let isPrime = num > 1;
    if (num > 1 && num < 100) {
      for (let d = 2; d * d <= num; d++) {
        if (num % d === 0) { isPrime = false; break; }
      }
    } else {
      isPrime = false;
    }
    if (isPrime && px < win2w - 20 && px >= 0) {
      primeViz = 0.25 + Math.sin(t * 2 + num * 0.3) * 0.1;
    }
  }

  // Apply UI
  if (bdr1 || bdr2) {
    r = 0; g = 200 + Math.sin(t * 2) * 55; b = 255;
  } else if (title1 || title2) {
    r = 0; g = 40; b = 80;
    // Simulate text dots
    if (x - (title1 ? win1x : win2x) > 5 && x - (title1 ? win1x : win2x) < 100 && y - (title1 ? win1y : win2y) > 4 && y - (title1 ? win1y : win2y) < 12) {
      r = 0; g = 220; b = 255;
    }
  } else if (inW1 || inW2) {
    r *= 0.15; g *= 0.15; b *= 0.15;
    r += dataBar * 0 + dataBar * 50;
    g += dataBar * 255;
    b += dataBar * 180;
    r += primeViz * 255;
    g += primeViz * 50;
    b += primeViz * 200;
  } else if (statusBar) {
    r = 5; g = 10; b = 30;
    if (y === 226) { r = 0; g = 150; b = 255; }
    // Status indicators
    for (let i = 0; i < 5; i++) {
      const sx2 = 10 + i * 90;
      if (x >= sx2 && x < sx2 + 15 && y === 232) {
        const on = Math.sin(t * 0.5 + i) > 0;
        r = on ? 0 : 30; g = on ? 255 : 30; b = on ? 100 : 30;
      }
    }
  }

  // Add grid
  if (!inW1 && !inW2 && !statusBar) {
    r += gridLine * 100;
    g += gridLine * 200;
    b += gridLine * 255;
  }

  // Glow effect for high reaction
  const glow = Math.max(0, reaction) ** 3;
  r += glow * 80;
  g += glow * 120;
  b += glow * 150;

  return [
    Math.min(255, Math.max(0, r)) | 0,
    Math.min(255, Math.max(0, g)) | 0,
    Math.min(255, Math.max(0, b)) | 0
  ];
}
